// Fictional cedent treaty: two scheduled portfolio reference areas, not property claims.
const scheduledAreas=[{id:'MOJAVE',name:'Mojave portfolio area',point:[-117.4,35.8],allocation:6000000},{id:'WESTERN',name:'Western portfolio area',point:[-118.2,35.4],allocation:4000000}];
const cedent={id:'DEMO-CEDENT-01',name:'Sierra Mutual — fictional insurer'};
[[5,'Ridgecrest',[-117.67,35.62]],[6,'Trona',[-117.37,35.76]],[7,'Tehachapi',[-118.45,35.13]],[2,'Lancaster',[-118.14,34.70]]].forEach(([i,name,point])=>{cities[i]=name;exposurePoints[i]=point;});
const portfolioMembership={5:'MOJAVE',6:'MOJAVE',7:'WESTERN',2:'WESTERN'};
const previousShowLocation=showLocation;showLocation=function(i){previousShowLocation(i);const id=portfolioMembership[i],area=scheduledAreas.find(a=>a.id===id);$('location').insertAdjacentHTML('beforeend',`<p class="small" style="margin-top:10px">${area?'Contextual portfolio grouping: '+area.name+'.':'Outside the two scheduled demo portfolio groups.'} Recovery uses the scheduled reference and allocation, not this site's damage or value.</p>`);};
state.area=0;state.fixture='main';
treaties.splice(0,treaties.length,{id:'DEMO-CA-PARAMETRIC',name:'California Portfolio Earthquake Treaty',short:'California portfolio',version:'2',point:scheduledAreas[0].point,ref:scheduledAreas[0].name,limit:10000000,start:'2019-01-01T00:00:00.000Z',end:'2020-01-01T00:00:00.000Z',areas:scheduledAreas});
function configureFixture(){const t=treaties[0],missing=state.fixture==='missing',zero=state.fixture==='zero';t.id=missing?'DEMO-CA-INCOMPLETE':zero?'DEMO-CA-HIGH-THRESHOLD':'DEMO-CA-PARAMETRIC';t.version='2';t.name=missing?'California Treaty — missing coverage':zero?'California Treaty — M7.5 minimum':'California Portfolio Earthquake Treaty';t.minimum=zero?7.5:null;t.missing=missing;t.start=missing?null:'2019-01-01T00:00:00.000Z';t.end=missing?null:'2020-01-01T00:00:00.000Z';t.point=scheduledAreas[state.area].point;t.ref=scheduledAreas[state.area].name;}
function assessPortfolio(e,t,selectedArea=0){const areas=t.areas.map(a=>({...a,...assess(e,{...t,point:a.point,limit:a.allocation})})),exceptions=[...new Set(areas.flatMap(a=>a.exceptions))],uncapped=exceptions.length?null:areas.reduce((sum,a)=>sum+a.amount,0),amount=uncapped===null?null:Math.min(t.limit,uncapped),selected=areas[selectedArea]||areas[0];return{...selected,areas,exceptions,uncapped,amount,eventCap:t.limit,status:exceptions.length?'Needs review':!areas[0].inCoverage?'Outside coverage':amount>0?'Trigger met':'Not triggered'};}
evaluate=()=>assessPortfolio(evidence(),treaties[0],state.area);
// The active-area selection changes the map/detail only; it never changes the evaluation.
const priorActiveRecord=activeRecord;
activeRecord=function(){configureFixture();const r=priorActiveRecord();if(r){r.contractName=r.contractName||treaties[0].name;r.contractId=r.contractId||treaties[0].id;r.fixture=r.fixture||state.fixture;}return r;};
function areaRows(c){return c.areas.map((a,i)=>`<button class="area-card ${state.area===i?'selected':''}" data-area="${i}"><strong>${a.name}</strong><span class="area-value">${money(a.amount)}</span><small>${a.distance.toFixed(1)} km · ${bandLabel(a.band)}<br>${a.pct*100}% × ${money(a.allocation)} allocation</small></button>`).join('');}
function selectArea(i){state.area=i;configureFixture();if(state.treaty===null)chooseTreaty(0);else{render();frame();}}
const priorPortfolioRender=render;
render=function(){configureFixture();priorPortfolioRender();$('frame').textContent=state.treaty===null?'↗ Focus event':'↗ Focus treaty areas';
 if(state.event===null){$('inspector').innerHTML=`<div class="welcome"><div class="micro">Cedent / fictional</div><h1>${cedent.name}</h1><p>The insurer buys earthquake liquidity protection for two scheduled portfolio areas.</p><div class="step"><i>1</i><div><b>Select an earthquake</b><p class="small">Independent event evidence feeds the contractual trigger.</p></div></div><div class="step"><i>2</i><div><b>Assess each scheduled area</b><p class="small">Magnitude and distance determine a percentage of its agreed allocation.</p></div></div><div class="step"><i>3</i><div><b>Explain the treaty total</b><p class="small">Sum the two contributions, then apply the $10m event cap.</p></div></div><div class="step"><i>4</i><div><b>Hand off to RAS</b><p class="small">The recovery is payable to the insurer, not individual property owners.</p></div></div><div class="foot">FICTIONAL REINSURANCE TERMS · NO LOSS ESTIMATE<br>Can the analyst trace portfolio area → contribution → treaty recovery?</div></div>`;return;}
 const c=evaluate(0),e=evidence(),t=treaties[0],r=state.treaty===null?null:activeRecord();
 $('dock').innerHTML=`<div class="dockhead"><span class="micro">One treaty · two scheduled areas</span><span class="total-label">Total: ${money(c.amount)}</span></div><div id="treaties" hidden></div><div class="area-grid">${areaRows(c)}</div><div class="aggregation-note">${c.amount===null?'No treaty amount: required coverage is missing.':`${money(c.areas[0].amount)} + ${money(c.areas[1].amount)} = ${money(c.uncapped)} · event cap ${money(t.limit)} → ${money(c.amount)}`}</div>`;
 document.querySelectorAll('[data-area]').forEach(b=>b.onclick=()=>selectArea(+b.dataset.area));
 if(!r){$('inspector').querySelector('h3').textContent='One treaty protects the cedent’s portfolio.';$('inspector').querySelector('h3').nextElementSibling.textContent='Select a scheduled area below. Its allocation is a contractual payout amount, not insured value or actual claims.';$('inspectfirst').textContent='Explain the treaty recovery →';return;}
 const a=c.areas[state.area];
 $('inspector').innerHTML=`<div class="pad"><div class="micro">${cedent.name} / imported from simulated RAS</div><h1>${t.name}</h1><span class="status ${c.amount===null||c.amount===0?'warn':''}">${c.status} · ${r.packet?'Demo reviewed':'Review pending'}</span><div class="small">${t.id} · contract v2 · evaluation v${r.version}</div>${state.fixture!=='main'?'<div class="version-note">Separate fictional contract variant; not the main treaty.</div>':''}</div><div class="metric"><div class="micro">Total provisional treaty recovery · to the cedent</div><div class="amount">${money(c.amount)}${c.amount===null?'':'<small>USD</small>'}</div><p class="small">${c.amount===null?'Required coverage dates unavailable; no amount asserted.':`${money(c.areas[0].amount)} + ${money(c.areas[1].amount)} · capped at ${money(t.limit)}`}</p></div><div class="pad"><div class="tabs"><button data-tab="conditions" class="${state.tab==='conditions'?'active':''}">Area calculation</button><button data-tab="evidence" class="${state.tab==='evidence'?'active':''}">Evidence & revisions</button></div>${state.tab==='conditions'?`<div class="micro">Selected scheduled area</div><h2>${a.name}</h2><div class="row"><span>Fixed reference latitude, longitude</span><b>${a.point[1]}, ${a.point[0]}</b></div><div class="row"><span>Epicentre distance / band</span><b>${a.distance.toFixed(1)} km / ${bandLabel(a.band)}</b></div><div class="row"><span>Contractual allocation</span><b>${money(a.allocation)} USD</b></div>${matrix(0)}<div class="calc">M${e.mag} · ${a.distance.toFixed(1)} km → ${a.pct*100}% × ${money(a.allocation)} = <b>${money(a.amount)}</b> contribution.</div><h3 style="margin-top:18px">Treaty aggregation</h3><p class="small">Each scheduled area contributes once. Overlapping circles may both trigger; the contract explicitly adds their contributions. Inner/outer rates within an area are exclusive.</p><div class="row"><span>Event cap</span><b>${money(t.limit)}</b></div><div class="row"><span>Coverage UTC</span><b>${t.missing?'Missing — Needs review':'[2019-01-01, 2020-01-01)'}</b></div><p class="small">Allocations are agreed payout limits, not sums of insured property values. No loss amount is derived from these circles.</p>`:`<div class="row"><span>Event record</span><b>${e.source}</b></div><div class="row"><span>Occurrence UTC</span><b>${e.date}</b></div><div class="row"><span>Observation</span><b>${e.label}</b></div><div class="row"><span>Magnitude / type</span><b>${e.mag} / mw</b></div>${replay()}<p class="small">A changed observation recomputes both area contributions and the treaty total. Earlier reviewed versions remain in history. Source-byte archive is not packaged in this UI study.</p>`}<button class="primary" id="handoff">${c.amount===null?'Inspect exception & missing information ↗':'Review total treaty handoff ↗'}</button><div class="foot">PROVISIONAL REINSURANCE RECOVERY · NOT PROPERTY CLAIM PAYMENTS</div></div>`;
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render();});$('handoff').onclick=openPacket;
 if($('snapshot'))$('snapshot').oninput=ev=>{invalidate();state.snapshot=+ev.target.value;render();};
 $('mapsub').textContent='Two scheduled areas → contributions → capped treaty recovery';
};
const priorMakePacket=makePacket;
makePacket=function(r){const p=priorMakePacket(r),c=r.assessment;delete p.calculation.referencePoint;delete p.calculation.distanceKm;delete p.calculation.band;delete p.calculation.magnitudeRow;delete p.calculation.matrixRate;p.cedent=cedent;p.contract.areas=scheduledAreas.map(a=>({id:a.id,name:a.name,referencePoint:{longitude:a.point[0],latitude:a.point[1]},allocation:a.allocation,currency:'USD'}));p.calculation.ruleVersion='4-portfolio';p.calculation.areaAssessments=c.areas.map(a=>({areaId:a.id,distanceKm:a.distance,band:bandLabel(a.band),magnitudeRow:rows[a.row]?.label,matrixRate:a.pct,allocation:a.allocation,contribution:a.amount,status:a.status}));p.calculation.aggregation={method:'Sum each scheduled area once, capped at treaty event limit',uncappedTotal:c.uncapped,eventCap:c.eventCap,totalRecovery:c.amount,overlappingAreas:'Both may contribute; no duplicate contribution within an area'};p.notice+=' Recovery is payable to the cedent insurer; allocations are not insured values or individual policyholder claim amounts.';return p;};
const priorExceptionPacket=exceptionPacket;
exceptionPacket=function(r){const p=priorExceptionPacket(r);p.cedent=cedent;p.knownConditions={areaAssessments:r.assessment.areas.map(a=>({areaId:a.id,distanceKm:a.distance,matrixRate:a.pct,contribution:null}))};return p;};
const priorOpenPortfolioPacket=openPacket;
openPacket=function(){priorOpenPortfolioPacket();const r=activeRecord();if(!r)return;const c=r.assessment,t=treaties[0],e=evidence();$('packet').innerHTML=summaryRows([['Beneficiary / cedent',cedent.name],['Evaluation / packet',`v${r.version} / ${r.packet?.packetId||'Created on review'}`],['Event / observation',`${e.name} / ${e.label}`],['Occurrence UTC',e.date],['RAS contract / version',`${t.id} / v2`],...c.areas.map(a=>[a.name,`${a.distance.toFixed(3)} km · ${a.pct*100}% × ${money(a.allocation)} = ${money(a.amount)}`]),['Uncapped sum',money(c.uncapped)],['Treaty event cap',money(c.eventCap)],['Total full recovery',`${money(c.amount)} USD · ${c.status}`],['Previous packet',precedingPacket(r)?.packet.packetId||'None'],['Existing RAS reference',knownReference(r.prior)||'None'],['Exceptions',c.exceptions.join('; ')||'None']]);};
applyStep=function(n){const previousEvent=state.event,previousSnapshot=state.snapshot;invalidate();state.free=false;state.step=n;state.fixture=state.scenario==='missing'?'missing':state.scenario==='zero'?'zero':'main';state.event=n===0?null:state.scenario==='outer'?2:0;state.treaty=n>=3?0:null;state.region=n>0;state.area=state.scenario==='outer'?1:0;state.snapshot=n>1&&previousEvent===state.event?previousSnapshot:state.scenario==='revision'?0:1;state.tab=n>=4?'evidence':'conditions';configureFixture();render();frame();if(n===5)openPacket();};
const priorAreaTour=renderTour;renderTour=function(){priorAreaTour();if(!state.free){const titles=['Explore the cedent’s portfolio','Select the earthquake','Compare scheduled area contributions','Explain the capped treaty recovery','Inspect evidence and revisions','Review the treaty handoff'];$('tourtitle').textContent=`${state.step+1} / 6 · ${titles[state.step]}`;if(state.step===3)$('tourdesc').textContent='Select an area to inspect its circles and matrix. Both contributions feed one treaty recovery.';}};
